mod auth {
    pub struct Permission { _guard: () }
    pub fn login(pass: &str) -> Option<Permission> {
        if pass == "admin" { Some(Permission { ⟦slot1⟧ }) }
        else { None }
    }
}

fn access_db(_p: ⟦slot2⟧) -> &'static str { "granted" }

fn main() {
    let token = auth::login("admin").unwrap();
    assert_eq!(access_db(token), "granted");
}

tests:
#[test]
fn test_token_auth() {
    let token = auth::login("admin");
    assert!(token.is_some());
    assert_eq!(access_db(token.unwrap()), "granted");
}
